import argparse
import csv
import json
from datetime import date


def go():
    parser = argparse.ArgumentParser()
    parser.add_argument("file")
    parser.add_argument("--format", choices=("text", "json"), default="text")
    parser.add_argument("--since", metavar="YYYY-MM-DD")
    args = parser.parse_args()

    since = None
    if args.since:
        try:
            since = date.fromisoformat(args.since)
        except ValueError:
            parser.error("--since must be a date in YYYY-MM-DD format")
        if since.isoformat() != args.since:
            parser.error("--since must be a date in YYYY-MM-DD format")

    total_revenue = 0
    total_tax = 0
    by_region = {}
    by_product = {}
    rows = 0

    with open(args.file, newline="") as f:
        reader = csv.reader(f)
        next(reader, None)
        for fields in reader:
            if len(fields) < 5:
                continue
            if since is not None:
                try:
                    sale_date = date.fromisoformat(fields[0])
                except ValueError:
                    continue
                if sale_date < since:
                    continue
            try:
                units = int(fields[3])
                price = float(fields[4])
            except ValueError:
                continue

            amount = units * price
            if units >= 50:
                amount -= amount * 0.1
            elif units >= 10:
                amount -= amount * 0.05

            region = fields[1]
            if region == "north":
                tax = amount * 0.07
            elif region == "south":
                tax = amount * 0.05
            elif region == "east":
                tax = amount * 0.06
            elif region == "west":
                tax = amount * 0.08
            else:
                tax = 0

            total_revenue += amount
            total_tax += tax
            by_region[region] = by_region.get(region, 0) + amount
            by_product[fields[2]] = by_product.get(fields[2], 0) + amount
            rows += 1

    top_product = max(by_product, key=by_product.get) if by_product else None
    if args.format == "json":
        result = {
            "rows": rows,
            "total_revenue": round(total_revenue, 2),
            "total_tax": round(total_tax, 2),
            "by_region": {key: round(value, 2) for key, value in sorted(by_region.items())},
            "by_product": {key: round(value, 2) for key, value in sorted(by_product.items())},
            "top_product": top_product,
        }
        print(json.dumps(result))
        return

    print("SALES REPORT")
    print("============")
    print("Rows: " + str(rows))
    print("Total revenue: " + str(round(total_revenue, 2)))
    print("Total tax: " + str(round(total_tax, 2)))
    print("")
    print("By region:")
    for key in sorted(by_region):
        print("  " + key + ": " + str(round(by_region[key], 2)))
    print("")
    print("By product:")
    for key in sorted(by_product):
        print("  " + key + ": " + str(round(by_product[key], 2)))
    print("")
    best_value = by_product.get(top_product, 0)
    print("Top product: " + str(top_product) + " (" + str(round(best_value, 2)) + ")")


if __name__ == "__main__":
    go()
